147	    void collectShape(cpShape* shape, void* data)
148	    {
149	        std::vector<PhysicsShape*>* results = static_cast<std::vector<PhysicsShape*>*>(data);
150	        PhysicsShape* physicsShape = toPhysicsShape(shape);
151	
152	        if (results == nullptr || physicsShape == nullptr)
153	        {
154	            return;
155	        }
156	
157	        // One PhysicsShape can own several cpShapes, so the same owner may be reported twice.
158	        appendUnique(*results, physicsShape);
159	    }
