174	    struct BodyDistance
175	    {
176	        PhysicsBody* body;
177	        float distance;
178	    };
179	
180	    struct CircleCollector
181	    {
182	        cpVect center;
183	        cpFloat radius;
184	        std::vector<BodyDistance> bodies;
185	    };
186	
187	    void collectCircleShape(cpShape* shape, void* data)
188	    {
189	        CircleCollector* collector = static_cast<CircleCollector*>(data);
190	        PhysicsBody* body = toPhysicsBody(shape);
191	
192	        if (collector == nullptr || body == nullptr)
193	        {
194	            return;
195	        }
196	
197	        // The bounding box test is only a broad phase; measure the real surface distance here.
198	        cpPointQueryInfo info = { nullptr, cpvzero, 0.0, cpvzero };
199	        cpShapePointQuery(shape, collector->center, &info);
200	
201	        if (info.distance > collector->radius)
202	        {
203	            return;
204	        }
205	
206	        const float distance = info.distance > 0.0 ? PhysicsHelper::cpfloat2float(info.distance) : 0.0f;
207	
208	        for (auto& entry : collector->bodies)
209	        {
210	            if (entry.body == body)
211	            {
212	                if (distance < entry.distance)
213	                {
214	                    entry.distance = distance;
215	                }
216	                return;
217	            }
218	        }
219	
220	        BodyDistance entry = { body, distance };
221	        collector->bodies.push_back(entry);
222	    }
223	
224	    struct ContactCollector
225	    {
226	        std::vector<cpArbiter*> visited;
227	        std::vector<PhysicsContactPairInfo> pairs;
228	    };
229	
230	    void collectArbiter(cpBody* /*body*/, cpArbiter* arbiter, void* data)
231	    {
232	        ContactCollector* collector = static_cast<ContactCollector*>(data);
233	
234	        if (collector == nullptr || arbiter == nullptr)
235	        {
236	            return;
237	        }
238	
239	        // Both bodies of a colliding pair list the same arbiter, so it is recorded only once.
240	        if (std::find(collector->visited.begin(), collector->visited.end(), arbiter) != collector->visited.end())
241	        {
242	            return;
243	        }
244	        collector->visited.push_back(arbiter);
245	
246	        cpShape* cpShapeA = nullptr;
247	        cpShape* cpShapeB = nullptr;
248	        cpArbiterGetShapes(arbiter, &cpShapeA, &cpShapeB);
249	
250	        PhysicsBody* bodyA = toPhysicsBody(cpShapeA);
251	        PhysicsBody* bodyB = toPhysicsBody(cpShapeB);
252	
253	        if (bodyA == nullptr || bodyB == nullptr)
254	        {
255	            return;
256	        }
257	
258	        PhysicsContactPairInfo info;
259	        info.bodyA = bodyA;
260	        info.bodyB = bodyB;
261	        info.contactPoint = Vec2::ZERO;
262	        info.contactNormal = PhysicsHelper::cpv2point(cpArbiterGetNormal(arbiter));
263	        info.penetration = 0.0f;
264	
265	        const int count = cpArbiterGetCount(arbiter);
266	        if (count > 0)
267	        {
268	            Vec2 sum = Vec2::ZERO;
269	            for (int i = 0; i < count; ++i)
270	            {
271	                const Vec2 pointA = PhysicsHelper::cpv2point(cpArbiterGetPointA(arbiter, i));
272	                const Vec2 pointB = PhysicsHelper::cpv2point(cpArbiterGetPointB(arbiter, i));
273	                sum += (pointA + pointB) * 0.5f;
274	
275	                // Chipmunk reports overlap as a negative distance, so take the magnitude.
276	                const float depth = std::fabs(PhysicsHelper::cpfloat2float(cpArbiterGetDepth(arbiter, i)));
277	                if (depth > info.penetration)
278	                {
279	                    info.penetration = depth;
280	                }
281	            }
282	
283	            info.contactPoint = sum / static_cast<float>(count);
284	        }
285	
286	        collector->pairs.push_back(info);
287	    }
288	
289	    void collectBodyArbiters(cpBody* body, void* data)
290	    {
291	        if (body == nullptr)
292	        {
293	            return;
294	        }
295	
296	        cpBodyEachArbiter(body, collectArbiter, data);
297	    }
