325	PhysicsNearestResult PhysicsWorldQuery::queryNearestPoint(const Vec2& point, float maxDistance, unsigned int categoryMask)
326	{
327	    // A null shape paired with distance -1 is the "nothing found" answer. A real hit can also
328	    // report a negative distance: that means the query point lies inside the shape.
329	    PhysicsNearestResult result = { nullptr, Vec2::ZERO, -1.0f, Vec2::ZERO };
330	
331	    if (!_initialized || _space == nullptr)
332	    {
333	        return result;
334	    }
335	
336	    cpPointQueryInfo info = { nullptr, cpvzero, 0.0, cpvzero };
337	    cpShape* shape = cpSpacePointQueryNearest(_space,
338	                                              PhysicsHelper::point2cpv(point),
339	                                              maxDistance,
340	                                              makeCategoryFilter(categoryMask),
341	                                              &info);
342	
343	    PhysicsShape* physicsShape = toPhysicsShape(shape);
344	    if (physicsShape == nullptr)
345	    {
346	        return result;
347	    }
348	
349	    result.shape = physicsShape;
350	    result.point = PhysicsHelper::cpv2point(info.point);
351	    result.distance = PhysicsHelper::cpfloat2float(info.distance);
352	    result.gradient = PhysicsHelper::cpv2point(info.gradient);
353	
354	    return result;
355	}
