625	float PhysicsWorldQuery::computePathClearance(const Vec2* path, int pathCount, unsigned int blockMask)
626	{
627	    // A degenerate path has no legs to measure; -1 is the sentinel for "no clearance computed".
628	    if (path == nullptr || pathCount < 2 || !_initialized || _space == nullptr)
629	    {
630	        return -1.0f;
631	    }
632	
633	    const cpShapeFilter filter = makeCategoryFilter(blockMask);
634	
635	    // Nothing blocking within the horizon reports the horizon itself as the clearance.
636	    float clearance = kQueryHorizon;
637	
638	    for (int i = 0; i + 1 < pathCount; ++i)
639	    {
640	        const Vec2& from = path[i];
641	        const Vec2& to = path[i + 1];
642	        const cpVect cpFrom = PhysicsHelper::point2cpv(from);
643	        const cpVect cpTo = PhysicsHelper::point2cpv(to);
644	
645	        // A leg that a blocking shape crosses has no clearance at all, and no later leg can
646	        // push the minimum below zero, so the answer is settled.
647	        if (cpSpaceSegmentQueryFirst(_space, cpFrom, cpTo, 0.0f, filter, nullptr) != nullptr)
648	        {
649	            return 0.0f;
650	        }
651	
652	        const int samples = clearanceSampleCount(from.distance(to));
653	        for (int s = 0; s < samples; ++s)
654	        {
655	            const float t = static_cast<float>(s) / static_cast<float>(samples - 1);
656	            const Vec2 sample = from + (to - from) * t;
657	            const float distance = nearestSurfaceDistance(_space, PhysicsHelper::point2cpv(sample), filter, kQueryHorizon);
658	
659	            if (distance >= 0.0f && distance < clearance)
660	            {
661	                clearance = distance;
662	            }
663	        }
664	    }
665	
666	    return clearance;
667	}
